const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
const item = $input.first();
let raw;
try { raw = (await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'); }
catch (e) { raw = JSON.stringify(item.json.body); }
const ts = item.json.headers['x-lendloop-timestamp'];
const sig = item.json.headers['x-lendloop-signature'] || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret || '').update(ts + '.' + raw).digest('hex');
const a = Buffer.from(sig), b = Buffer.from(expected);
const fresh = Math.abs(Date.now() / 1000 - Number(ts)) <= 300;
const valid = Boolean(secret) && fresh && a.length === b.length && crypto.timingSafeEqual(a, b);
if (!valid) console.error('[LendLoop] rejected webhook: invalid or stale signature');
return [{ json: { valid, payload: valid ? JSON.parse(raw) : null } }];

const p = $json.payload;
const verbs = { pending: 'received a new borrow request for', approved: 'approved your request for', declined: 'declined your request for', returned: 'marked as returned:' };
const message = 'Hi ' + p.recipient.name + ', the ' + (p.recipient.role === 'owner' ? 'borrower' : 'lender') + ' ' + (verbs[p.status] || 'updated') + ' "' + p.tool.name + '" (' + p.dates.start + ' to ' + p.dates.end + ').';
// Mock delivery: replace with an email/chat node in production.
console.log('[LendLoop notification]', JSON.stringify({ to: p.recipient.name, message }));
return { json: { loanId: p.loanId, idempotencyKey: p.idempotencyKey, message } };

const crypto = require('crypto');
const secret = $env.LENDLOOP_HMAC_SECRET;
if (!secret) throw new Error('LENDLOOP_HMAC_SECRET is not set in the n8n environment');

const body = JSON.stringify({ kind: 'status_notification', idempotencyKey: $json.idempotencyKey, loanId: $json.loanId, status: 'sent', detail: 'Mock notification logged' });
const timestamp = String(Math.floor(Date.now() / 1000));
const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
return { json: { body, timestamp, signature } };
